"""Solo match lifecycle: creation, loading, preparation, aircraft, free fall, parachute, landing.

The engine advances `match.clock` and `match.tick` and then calls `tick_lifecycle`. This module
only drives phase transitions and airborne participants. Player actions return `(ok, detail)` and
never raise on bad client input. Every number comes from `SoloMatchConfig`; none of it is an
original Rules of Survival value.
"""

import math
import random

from solo_engine.config import DIFFICULTY_PROFILES, ConfigError, SoloMatchConfig, validate_config
from solo_engine.geometry import clamp_to_map, inside_any, normalize
from solo_engine.model import (
    Aircraft,
    BotBrain,
    LifeState,
    MapDefinition,
    MatchPhase,
    Participant,
    Rect,
    SoloMatch,
)

BOT_NAMES = (
    "Ash", "Birch", "Cedar", "Dune", "Ember", "Flint", "Gale", "Harbor", "Iris", "Juniper",
    "Kestrel", "Lumen", "Moss", "Nova", "Onyx", "Pike", "Quill", "Rook", "Sable", "Thorn",
    "Umber", "Vale", "Wren", "Yarrow", "Zephyr",
)  # fmt: skip

ROUTE_EDGE_MARGIN = 0.05  # fraction of map size the route extends beyond each edge
ROUTE_CENTRE_OFFSET = 0.25  # max perpendicular distance of the route from the centre, x size
LANDING_SEARCH_STEP = 0.5  # metres between rings when nudging a landing out of a blocker
SPAWN_MIN_SPACING = 1.0  # metres between participants on the preparation island
CLIENT_FALL_FLOOR = 1.0  # metres: lowest engine z for a human whose fall the client owns
_AIRBORNE = (LifeState.FREEFALL, LifeState.PARACHUTE)

Result = tuple[bool, str]


# ---------------------------------------------------------------------------------------------
# creation


def create_solo_match(
    config: SoloMatchConfig,
    map_def: MapDefinition,
    human_ids: list[tuple[str, str]],
    match_id: str | None = None,
) -> SoloMatch:
    """Build a match in LOADING with humans in slots 0.. and bots after them."""
    validate_config(config, (map_def.map_id,))
    if map_def.size <= 0:
        raise ConfigError("Map size must be positive")
    if not human_ids:
        raise ConfigError("A solo match needs a human player")
    if len(human_ids) > config.real_players:
        raise ConfigError("More humans than the match allows")
    seen: set[str] = set()
    for entry in human_ids:
        if not (isinstance(entry, tuple) and len(entry) == 2 and isinstance(entry[0], str) and entry[0]):
            raise ConfigError("Invalid human participant entry")
        if entry[0] in seen or entry[0].startswith("bot-"):
            raise ConfigError(f"Duplicate or reserved participant id {entry[0]!r}")
        seen.add(entry[0])
    bot_count = config.bot_count if config.auto_fill_bots else 0
    if len(human_ids) + bot_count > config.max_players:
        raise ConfigError("Too many participants for the match")

    rng = random.Random(config.seed) if config.seed is not None else random.Random()
    if match_id is None:
        match_id = f"solo-{rng.getrandbits(48):012x}"
    match = SoloMatch(match_id=match_id, config=config, map=map_def, rng=rng)
    match.phase = MatchPhase.LOADING
    match.phase_started_at = match.clock
    match.phase_ends_at = match.clock + config.loading_timeout

    spots = _island_spots(match, len(human_ids) + bot_count)
    slot = 0
    for participant_id, display_name in human_ids:
        x, y = spots[slot]
        match.participants[participant_id] = Participant(
            participant_id=participant_id,
            display_name=str(display_name)[:32] or participant_id,
            is_bot=False,
            slot=slot,
            x=x,
            y=y,
            health=config.max_health,
            max_health=config.max_health,
        )
        slot += 1

    for n in range(1, bot_count + 1):
        bot_id = f"bot-{n}"
        x, y = spots[slot]
        difficulty = config.bot_difficulty
        if difficulty == "mixed":
            difficulty = rng.choice(("easy", "normal", "hard"))
        brain = BotBrain(profile=DIFFICULTY_PROFILES[difficulty], jump_at_progress=rng.uniform(0.1, 0.85))
        name = BOT_NAMES[(n - 1) % len(BOT_NAMES)]
        if n > len(BOT_NAMES):
            name = f"{name}{(n - 1) // len(BOT_NAMES) + 1}"
        match.participants[bot_id] = Participant(
            participant_id=bot_id,
            display_name=name,
            is_bot=True,
            slot=slot,
            appearance={
                "outfit": f"dev-{rng.randint(1, 8)}",
                "hair": f"dev-{rng.randint(1, 6)}",
                "face": f"dev-{rng.randint(1, 4)}",
            },
            x=x,
            y=y,
            health=config.max_health,
            max_health=config.max_health,
            loaded=True,
            brain=brain,
        )
        slot += 1

    match.emit(
        "match_created",
        match_id=match.match_id,
        map_id=map_def.map_id,
        humans=len(human_ids),
        bots=bot_count,
    )
    return match


def _island_spots(match: SoloMatch, count: int) -> list[tuple[float, float]]:
    """Distinct random points inside the preparation island and outside blockers."""
    island: Rect = match.map.prep_island
    blockers = match.map.blockers
    spots: list[tuple[float, float]] = []
    attempts = 0
    while len(spots) < count and attempts < count * 200:
        attempts += 1
        x = match.rng.uniform(island.min_x, island.max_x)
        y = match.rng.uniform(island.min_y, island.max_y)
        if inside_any(x, y, blockers):
            continue
        if any(math.hypot(x - sx, y - sy) < SPAWN_MIN_SPACING for sx, sy in spots):
            continue
        spots.append((x, y))
    if len(spots) < count:
        # Crowded island: walk a fine grid and accept any free, unused point.
        step = 0.25
        width = max(island.max_x - island.min_x, 0.0)
        height = max(island.max_y - island.min_y, 0.0)
        used = set(spots)
        for i in range(int(width / step) + 1):
            for j in range(int(height / step) + 1):
                if len(spots) >= count:
                    break
                point = (island.min_x + i * step, island.min_y + j * step)
                if point in used or inside_any(point[0], point[1], blockers):
                    continue
                used.add(point)
                spots.append(point)
    if len(spots) < count:
        raise ConfigError("Preparation island has no room for every participant")
    return spots


# ---------------------------------------------------------------------------------------------
# phases


def _set_phase(match: SoloMatch, phase: MatchPhase, duration: float | None = None) -> None:
    match.phase = phase
    match.phase_started_at = match.clock
    match.phase_ends_at = match.clock + duration if duration is not None else match.clock
    match.emit("phase", phase=phase.value, ends_at=match.phase_ends_at)


def _enter_preparation(match: SoloMatch) -> None:
    for human in match.humans():
        if not human.loaded:
            human.connected = False
    _set_phase(match, MatchPhase.PREPARATION, match.config.warmup_seconds)


def _all_humans_loaded(match: SoloMatch) -> bool:
    humans = match.humans()
    return bool(humans) and all(h.loaded for h in humans)


def mark_loaded(match: SoloMatch, participant_id: str) -> Result:
    participant = _get(match, participant_id)
    if participant is None:
        return False, "unknown participant"
    if match.phase == MatchPhase.CLOSED:
        return False, "match closed"
    participant.loaded = True
    participant.connected = True
    if match.phase == MatchPhase.LOADING and _all_humans_loaded(match):
        _enter_preparation(match)
    return True, "loaded"


def cancel(match: SoloMatch, participant_id: str) -> Result:
    participant = _get(match, participant_id)
    if participant is None:
        return False, "unknown participant"
    if participant.is_bot:
        return False, "bots cannot cancel"
    if match.phase not in (MatchPhase.LOADING, MatchPhase.PREPARATION):
        return False, "match already started"
    del match.participants[participant_id]
    match.emit("participant_left", participant_id=participant_id)
    if not match.humans():
        _set_phase(match, MatchPhase.CLOSED)
        match.emit("cancelled", match_id=match.match_id)
        return True, "cancelled"
    if match.phase == MatchPhase.LOADING and _all_humans_loaded(match):
        _enter_preparation(match)
    return True, "left"


def make_flight_route(match: SoloMatch) -> Aircraft:
    """A straight route that crosses the whole map, entering and leaving just outside its edge."""
    size = match.map.size
    rng = match.rng
    theta = rng.uniform(0.0, 2.0 * math.pi)
    ux, uy = math.cos(theta), math.sin(theta)
    nx, ny = -uy, ux
    offset = rng.uniform(-ROUTE_CENTRE_OFFSET, ROUTE_CENTRE_OFFSET) * size
    px, py = size / 2 + nx * offset, size / 2 + ny * offset
    # Clip the infinite line p + t*u against the square [0, size]^2 (slab method).
    t_enter, t_exit = -math.inf, math.inf
    for p, u in ((px, ux), (py, uy)):
        if abs(u) < 1e-12:
            continue
        a, b = (0.0 - p) / u, (size - p) / u
        t_enter = max(t_enter, min(a, b))
        t_exit = min(t_exit, max(a, b))
    margin = ROUTE_EDGE_MARGIN * size
    t0, t1 = t_enter - margin, t_exit + margin
    config = match.config
    return Aircraft(
        start=(px + ux * t0, py + uy * t0),
        end=(px + ux * t1, py + uy * t1),
        altitude=config.aircraft_altitude,
        speed=config.aircraft_speed,
    )


def _enter_aircraft(match: SoloMatch) -> None:
    match.aircraft = make_flight_route(match)
    ax, ay = match.aircraft.position()
    for p in match.alive():
        p.life = LifeState.ON_AIRCRAFT
        p.x, p.y, p.z = ax, ay, match.aircraft.altitude
        p.steer_x = p.steer_y = 0.0
        p.move_x = p.move_y = 0.0  # island walking intent must not carry over to the landing
        p.sprinting = False
    _set_phase(match, MatchPhase.AIRCRAFT)
    match.emit(
        "aircraft",
        start=match.aircraft.start,
        end=match.aircraft.end,
        altitude=match.aircraft.altitude,
        speed=match.aircraft.speed,
    )


def tick_lifecycle(match: SoloMatch, dt: float) -> None:
    """Drive phase transitions and airborne participants. The engine has already advanced the clock."""
    if dt < 0 or not math.isfinite(dt):
        return
    config = match.config
    phase = match.phase

    if phase == MatchPhase.LOADING:
        if _all_humans_loaded(match):
            _enter_preparation(match)
        elif match.clock - match.phase_started_at >= config.loading_timeout:
            if any(h.loaded for h in match.humans()):
                _enter_preparation(match)  # the humans that did not load are disconnected
            else:  # nobody to play for: do not run a match without a viewer
                close_match(match, "loading_timeout")
        return

    if phase == MatchPhase.PREPARATION:
        if config.auto_start and match.clock >= match.phase_ends_at:
            _enter_aircraft(match)
        return

    if phase == MatchPhase.ENDED:
        _tick_airborne(match, dt)
        if match.clock >= match.phase_ends_at:
            _set_phase(match, MatchPhase.CLOSED)
        return

    if phase == MatchPhase.CLOSED:
        return

    _tick_airborne(match, dt)

    if phase == MatchPhase.AIRCRAFT:
        aircraft = match.aircraft
        if aircraft is None:  # defensive: should not happen
            _enter_playing(match)
            return
        length = aircraft.length
        if length > 1e-9:
            aircraft.progress = min(1.0, aircraft.progress + aircraft.speed * dt / length)
        else:
            aircraft.progress = 1.0
        ax, ay = aircraft.position()
        aboard = [p for p in match.participants.values() if p.life == LifeState.ON_AIRCRAFT]
        for p in aboard:
            p.x, p.y, p.z = ax, ay, aircraft.altitude
        if aircraft.progress >= 1.0 - config.forced_jump_margin:
            for p in aboard:
                _jump(match, p, forced=True)
        if not any(p.life == LifeState.ON_AIRCRAFT for p in match.participants.values()):
            _enter_playing(match)


def _enter_playing(match: SoloMatch) -> None:
    match.started_playing_at = match.clock
    _set_phase(match, MatchPhase.PLAYING)


def _tick_airborne(match: SoloMatch, dt: float) -> None:
    """Glide and fall for airborne participants.

    With `config.client_owns_human_fall`, a human's z never goes below CLIENT_FALL_FLOOR: the
    human lands on `report_landed`, or after `client_landing_timeout` seconds from the jump.
    Bots always land on the engine timeline.
    """
    config = match.config
    size = match.map.size
    for p in match.participants.values():
        if p.life == LifeState.FREEFALL:
            vertical, glide = config.freefall_speed, config.freefall_glide
        elif p.life == LifeState.PARACHUTE:
            vertical, glide = config.parachute_speed, config.parachute_glide
        else:
            continue
        sx, sy = normalize(p.steer_x, p.steer_y)
        nx, ny = clamp_to_map(p.x + sx * glide * dt, p.y + sy * glide * dt, size)
        p.stats.distance_travelled += math.hypot(nx - p.x, ny - p.y)
        p.x, p.y = nx, ny
        if sx or sy:
            p.yaw = math.atan2(sy, sx)
        p.z -= vertical * dt
        client_fall = config.client_owns_human_fall and not p.is_bot
        if client_fall:
            p.z = max(p.z, CLIENT_FALL_FLOOR)
        if p.life == LifeState.FREEFALL and p.z <= config.auto_deploy_height and p.z > 0:
            p.life = LifeState.PARACHUTE
            match.emit("parachute", participant_id=p.participant_id, auto=True)
        if client_fall:
            jumped_at = p.jumped_at if p.jumped_at is not None else match.clock
            if match.clock - jumped_at >= config.client_landing_timeout:
                _land(match, p, timeout=True)
        elif p.z <= 0:
            _land(match, p)


def _land(match: SoloMatch, p: Participant, **extra: object) -> None:
    p.z = 0.0
    p.x, p.y = find_free_point(match.map, p.x, p.y)
    p.life = LifeState.GROUNDED
    p.landed_at = match.clock
    p.steer_x = p.steer_y = 0.0
    match.emit("landed", participant_id=p.participant_id, x=p.x, y=p.y, **extra)


def find_free_point(map_def: MapDefinition, x: float, y: float) -> tuple[float, float]:
    """Nearest point inside the map and outside every blocker, searching outward in rings."""
    size = map_def.size
    blockers = map_def.blockers
    x, y = clamp_to_map(x, y, size)
    if not inside_any(x, y, blockers):
        return x, y
    step = LANDING_SEARCH_STEP
    radius = step
    while radius <= size * 1.5:
        count = max(8, int(2 * math.pi * radius / step))
        best: tuple[float, float] | None = None
        best_d = math.inf
        for k in range(count):
            angle = 2 * math.pi * k / count
            cx, cy = x + math.cos(angle) * radius, y + math.sin(angle) * radius
            if not (0.0 <= cx <= size and 0.0 <= cy <= size):
                continue
            if inside_any(cx, cy, blockers):
                continue
            d = math.hypot(cx - x, cy - y)
            if d < best_d:
                best, best_d = (cx, cy), d
        if best is not None:
            return best
        radius += step
    return x, y  # map entirely covered by blockers; nothing better exists


# ---------------------------------------------------------------------------------------------
# player actions


def _get(match: SoloMatch, participant_id: object) -> Participant | None:
    if not isinstance(participant_id, str):
        return None
    return match.participants.get(participant_id)


def _jump(match: SoloMatch, p: Participant, forced: bool = False) -> None:
    aircraft = match.aircraft
    if aircraft is not None:
        p.x, p.y = aircraft.position()
        p.z = aircraft.altitude
    p.life = LifeState.FREEFALL
    p.jumped_at = match.clock
    match.emit("jump", participant_id=p.participant_id, x=p.x, y=p.y, forced=forced)


def jump(match: SoloMatch, participant_id: str) -> Result:
    p = _get(match, participant_id)
    if p is None:
        return False, "unknown participant"
    if match.phase != MatchPhase.AIRCRAFT or match.aircraft is None:
        return False, "no aircraft"
    if p.life != LifeState.ON_AIRCRAFT:
        return False, "not on the aircraft"
    _jump(match, p)
    return True, "jumped"


def deploy_parachute(match: SoloMatch, participant_id: str) -> Result:
    p = _get(match, participant_id)
    if p is None:
        return False, "unknown participant"
    if p.life != LifeState.FREEFALL:
        return False, "not in free fall"
    p.life = LifeState.PARACHUTE
    match.emit("parachute", participant_id=p.participant_id, auto=False)
    return True, "parachute open"


def set_air_steer(match: SoloMatch, participant_id: str, x: float, y: float) -> Result:
    p = _get(match, participant_id)
    if p is None:
        return False, "unknown participant"
    if p.life not in (LifeState.ON_AIRCRAFT, LifeState.FREEFALL, LifeState.PARACHUTE):
        return False, "not airborne"
    try:
        fx, fy = float(x), float(y)
    except (TypeError, ValueError):
        return False, "invalid steer"
    if not (math.isfinite(fx) and math.isfinite(fy)):
        return False, "invalid steer"
    p.steer_x, p.steer_y = fx, fy
    return True, "steer set"


def _finite(value: object) -> float | None:
    if not isinstance(value, (int, float)) or isinstance(value, bool):
        return None
    try:
        number = float(value)
    except (OverflowError, TypeError, ValueError):
        return None
    return number if math.isfinite(number) else None


def report_landed(match: SoloMatch, participant_id: str, x: float | None = None, y: float | None = None) -> Result:
    """The client says this human touched the ground: land now (client physics decided it).

    Only a human in FREEFALL or PARACHUTE can land. An optional `x`, `y` (both or neither) must
    be finite; it is clamped to the map and moved out of any blocker. Emits `landed` with
    `reported=True`.
    """
    p = _get(match, participant_id)
    if p is None:
        return False, "unknown participant"
    if p.is_bot:
        return False, "bots land on the engine timeline"
    if p.life not in _AIRBORNE:
        return False, "not airborne"
    if (x is None) != (y is None):
        return False, "invalid position"
    if x is not None:
        fx, fy = _finite(x), _finite(y)
        if fx is None or fy is None:
            return False, "invalid position"
        p.x, p.y = clamp_to_map(fx, fy, match.map.size)
    _land(match, p, reported=True)
    return True, "landed"


def close_match(match: SoloMatch, reason: str) -> bool:
    """Move a match straight to CLOSED now (for example when every human left).

    Emits the usual `phase` event with `reason`. Returns False when it was already CLOSED.
    Ending the match and granting rewards first is the caller's job.
    """
    if match.phase == MatchPhase.CLOSED:
        return False
    match.phase = MatchPhase.CLOSED
    match.phase_started_at = match.phase_ends_at = match.clock
    match.emit("phase", phase=MatchPhase.CLOSED.value, ends_at=match.clock, reason=str(reason))
    return True


def end_match(match: SoloMatch, winner_id: str | None) -> None:
    if match.phase in (MatchPhase.ENDED, MatchPhase.CLOSED):
        return
    match.winner_id = winner_id
    _set_phase(match, MatchPhase.ENDED, match.config.results_seconds)
    match.emit("match_end", winner_id=winner_id)


# ---------------------------------------------------------------------------------------------
# views


def countdown_seconds_left(match: SoloMatch) -> float:
    """Seconds left on the preparation countdown; 0.0 in every other phase.

    For the gateway's countdown offset (docs/SOLO_GATEWAY_ADAPTER.md section 5.2).
    """
    if match.phase != MatchPhase.PREPARATION:
        return 0.0
    return max(0.0, match.phase_ends_at - match.clock)


def phase_view(match: SoloMatch) -> dict:
    timed = match.phase in (MatchPhase.LOADING, MatchPhase.PREPARATION, MatchPhase.ENDED)
    view: dict = {
        "phase": match.phase.value,
        "seconds_left": max(0.0, match.phase_ends_at - match.clock) if timed else None,
        "alive": len(match.alive()),
        "total": len(match.participants),
    }
    if match.aircraft is not None:
        ax, ay = match.aircraft.position()
        view["aircraft"] = {
            "x": ax,
            "y": ay,
            "z": match.aircraft.altitude,
            "start": match.aircraft.start,
            "end": match.aircraft.end,
            "progress": match.aircraft.progress,
        }
    return view
